// libs/cache_engine/include/cache_engine/measurement/ckpt/checkpoint_measure.hpp
// Die EINE uniforme Steuerzeile. ASCII-only.
// AM OBJEKT UEBERSETZT UND GELAUFEN: GCC 15.3 rc=0, clang 22.1 rc=0, -O2 -march=native
// -ftls-model=initial-exec -Winterference-size (keine Warnung). Probe:
// /home/comdare/.claude/jobs/5a19728e/tmp/entwurf/{checkpoint_measure.hpp,probe.cpp}

#include <array>
#include <concepts>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <source_location>
#include <string_view>
#include <type_traits>
#if defined(__x86_64__)
#include <immintrin.h>
#endif

namespace comdare::cache_engine::measurement::ckpt {

// == 1. DIE COMPILE-TIME TAGS ====================================================================
// Die drei Mess-Ebenen der Spezifikation. Der ZAHLENWERT ist die Ebenen-ORDNUNG: ein Checkpoint
// sucht seinen Aufrufer in der naechsthoeheren AKTIVEN Ebene (Macro zu Micro, Compare zu Macro).
// KEIN Laufzeit-Enum: der Wert reist ausschliesslich als Nichttyp-Template-Argument.
enum class Ebene : std::uint32_t { Compare = 0u, Macro = 1u, Micro = 2u };
inline constexpr std::size_t kEbenenZahl = 3u;

// IN/OUT als LEERE Tag-TYPEN. So steht der Tag an der Aufrufstelle woertlich dort, wo der Owner
// ihn hinschreibt ("checkpoint_measure(..., IN bzw. OUT)"), ohne dass ein Laufzeit-Wert entsteht:
// ein zustandsloses Objekt wird vollstaendig wegargumentiert, die Fallunterscheidung ist
// if constexpr. Kein Sprung, kein Laufzeit-switch, kein std::variant.
struct InTag {};
struct OutTag {};
inline constexpr InTag  IN{};
inline constexpr OutTag OUT{};

template <class T>
concept CheckpointTag = std::same_as<T, InTag> || std::same_as<T, OutTag>;

template <CheckpointTag T>
inline constexpr std::uint32_t kTagBit = std::same_as<T, OutTag> ? 1u : 0u;

// == 2. FEHLERKLASSEN (Pflicht) ==================================================================
// Form von topics/organ_axis_error_classes.hpp: STABILE string_view-Etiketten, KEIN eigenes Enum,
// damit kein zweiter Fehlerraum neben dem bestehenden entsteht.
inline constexpr std::string_view kCkptErrSlotUeberzaehlig = "ckpt_slot_ueberzaehlig";
inline constexpr std::string_view kCkptErrKeinSlot         = "ckpt_kein_slot";
inline constexpr std::string_view kCkptErrUeberlauf        = "ckpt_ueberlauf";
inline constexpr std::string_view kCkptErrOffenerIn        = "ckpt_offener_in";
inline constexpr std::string_view kCkptErrWaisenOut        = "ckpt_waisen_out";
inline constexpr std::string_view kCkptErrEbenenSprung     = "ckpt_ebenen_sprung";
inline constexpr std::string_view kCkptErrStempelInversion = "ckpt_stempel_inversion";
inline constexpr std::string_view kCkptErrStelleKollision  = "ckpt_stelle_kollision";
inline constexpr std::string_view kCkptErrNieAusgelesen    = "ckpt_nie_ausgelesen";

inline constexpr auto kCheckpointFehlerraum = std::array<std::string_view, 9>{
    kCkptErrSlotUeberzaehlig, kCkptErrKeinSlot,        kCkptErrUeberlauf,
    kCkptErrOffenerIn,        kCkptErrWaisenOut,       kCkptErrEbenenSprung,
    kCkptErrStempelInversion, kCkptErrStelleKollision, kCkptErrNieAusgelesen};
static_assert(kCheckpointFehlerraum.size() >= 1u, "leerer Fehlerraum ist die stille Luecke (FK-5)");

// == 3. DER LOG-EINTRAG ==========================================================================
struct alignas(16) CheckpointEintrag {
    std::uint32_t stelle;      // site_id:29 | ebene:2 | tag:1 -- EIN compile-time Immediate
    std::uint32_t reserviert;  // 0 -- haelt sizeof auf einer 2er-Potenz (Adressrechnung = shl, kein imul)
    std::uint64_t zeit;        // volle Zeitbasis dieses Checkpoints (Zykluszaehler)
};
static_assert(sizeof(CheckpointEintrag) == 16u);
static_assert(alignof(CheckpointEintrag) == 16u);
static_assert(std::is_trivially_copyable_v<CheckpointEintrag>);
static_assert(64u % sizeof(CheckpointEintrag) == 0u, "Satz muss die Cache-Line ohne Rest kacheln");

inline constexpr std::uint32_t kStelleBits = 29u;
inline constexpr std::uint32_t kStelleMax  = (1u << kStelleBits) - 1u;

template <std::uint32_t Stelle, Ebene E, CheckpointTag T>
inline constexpr std::uint32_t kStelleGepackt =
    (Stelle & kStelleMax) | (static_cast<std::uint32_t>(E) << 29u) | (kTagBit<T> << 31u);

// == 4. DER STATISCHE DESKRIPTOR JE AUFRUFSTELLE (GoF Flyweight) =================================
// Er wird im Hot-Path NIE angefasst. Er existiert nur, damit der Leser site_id -> Bedeutung
// aufloest. Deshalb steht im Eintrag eine ID und KEIN Zeiger: nach dlclose einer Tier-.so ist
// die Deskriptor-Adresse nachweislich nicht mehr gemappt, ein gespeicherter Zeiger baumelt.
struct CheckpointSite {
    std::uint32_t stelle;      // dieselbe site_id wie im Eintrag -- Aufloesung ohne Ordnungsannahme
    std::uint32_t zeile;       // source_location::line()
    Ebene         ebene;       // Vorgabe-Ebene dieser Aufrufstelle (aus COMDARE_CKPT_EBENE)
    std::uint32_t achsen_len;
    char const*   ziel;        // gelandete Zielfunktion (source_location::function_name())
    char const*   datei;
    char const*   achsen;      // Zeiger auf den GETEILTEN Achsen-Deskriptor (R1: nie kopiert)
};

namespace detail {
// Zwei-Pass-Senken -- 1:1 das Haus-Muster aus builder/build_variant_set_signature.hpp:118-127.
// Erst zaehlen, dann fuellen, beide Paesse ueber DENSELBEN Emitter: die Laenge kann nicht von der
// Ausgabe abweichen. Der Emitter soll dieselben Namens-/Zeichenvorrat-Wachen erben wie dort,
// sonst entsteht ein zweiter, ungewachter Signatur-Kanal.
struct CtCountSink { std::size_t n = 0; constexpr void put(char) noexcept { ++n; } };
struct CtFillSink  { char* p = nullptr; std::size_t n = 0; constexpr void put(char c) noexcept { p[n++] = c; } };
template <class Sink> constexpr void ct_put_text(Sink& s, std::string_view t) noexcept { for (char c : t) s.put(c); }

template <class Sink, class Konfig>
constexpr void ct_put_achsen(Sink& s) noexcept {
    ct_put_text(s, std::string_view{"ax=1;"});
    ct_put_text(s, Konfig::achsen_signatur());   // mp11-Typliste -> consteval-String, Haus-Mechanik
}
template <class Konfig> [[nodiscard]] consteval std::size_t achsen_len() noexcept {
    CtCountSink s{}; ct_put_achsen<CtCountSink, Konfig>(s); return s.n;
}
template <class Konfig, std::size_t N> [[nodiscard]] consteval std::array<char, N> achsen_chars() noexcept {
    std::array<char, N> out{}; CtFillSink s{out.data(), 0}; ct_put_achsen<CtFillSink, Konfig>(s); return out;
}
} // namespace detail

// EINE Kopie je Konfiguration und Binary -- von ALLEN Aufrufstellen derselben Konfiguration geteilt.
template <class Konfig>
inline constexpr auto kAchsenDeskriptorChars = detail::achsen_chars<Konfig, detail::achsen_len<Konfig>()>();

template <class Konfig>
[[nodiscard]] consteval CheckpointSite make_site(
    std::uint32_t stelle, Ebene ebene,
    std::source_location const loc = std::source_location::current()) noexcept {
    return CheckpointSite{stelle,
                          static_cast<std::uint32_t>(loc.line()),
                          ebene,
                          static_cast<std::uint32_t>(kAchsenDeskriptorChars<Konfig>.size()),
                          loc.function_name(),
                          loc.file_name(),
                          kAchsenDeskriptorChars<Konfig>.data()};
}

// == 5. VIRTUELLE THREAD-SLOTS ===================================================================
#if !defined(COMDARE_CKPT_SLOTS)
#error "COMDARE_CKPT_SLOTS fehlt -- die Obergrenze kommt compile-time aus der Thread-Unterachse."
#endif
inline constexpr std::uint32_t kCheckpointSlots = static_cast<std::uint32_t>(COMDARE_CKPT_SLOTS);
static_assert(kCheckpointSlots >= 1u);

// Der MUELL-SLOT. Ein Fluss ohne gueltige Nummer zeigt hierher; der Block hat Kapazitaet 0, also
// faengt ihn DIESELBE Kapazitaets-Verzweigung, die den Ueberlauf faengt. So kostet der Fehlerfall
// KEINEN eigenen Zweig im Hot-Path -- und es gibt trotzdem KEINEN Wrap-around.
inline constexpr std::uint32_t kSlotMuell = kCheckpointSlots;

// Die EINE Definition liegt in der beim START GELINKTEN gemeinsamen Mess-Bibliothek; jede
// Tier-.so DEKLARIERT sie nur. Damit traegt die Tier-.so KEIN eigenes TLS-Segment und verbraucht
// null statischen TLS-Vorrat (glibc: ~1665 Byte, PROZESSWEIT und kumulativ -- sechs .so mit je
// 256 B eigenem IE-TLS laden noch, die siebte bricht mit "cannot allocate memory in static TLS
// block", mitten im Messlauf). constinit ist PFLICHT und nicht Stil: es macht die Guard-Freiheit
// zu einer Uebersetzungs-Wache. Ohne constinit steht ueber der Modulgrenze ein nie genommener
// Guard-Zweig, der trotzdem je Zugriff kostet und im Quelltext unsichtbar ist.
extern constinit thread_local std::uint32_t t_slot;

// -Winterference-size: GCC 15.3 warnt hier REAL (am Objekt ausgeloest) -- und zu Recht, denn
// SlotBlock ist ABI-SICHTBAR: die Tier-.so liest die Tabelle, die die Mess-Bibliothek definiert.
// Ein zwischen -mtune-Werten wandernder alignas waere ein stiller ABI-Bruch. Deshalb eine EIGENE
// Konstante, wie GCC es selbst empfiehlt, je Plattform aus CMake gesetzt.
#if !defined(COMDARE_CKPT_LINE)
#define COMDARE_CKPT_LINE 64
#endif
inline constexpr std::size_t kCkptLine = static_cast<std::size_t>(COMDARE_CKPT_LINE);
static_assert(kCkptLine >= alignof(std::max_align_t) && (kCkptLine & (kCkptLine - 1u)) == 0u,
              "COMDARE_CKPT_LINE muss eine 2er-Potenz und mindestens max_align_t sein");

struct alignas(kCkptLine) SlotBlock {
    CheckpointEintrag* puffer        = nullptr;
    std::uint64_t      schreib_index = 0u;   // GEWOEHNLICH, kein std::atomic -- EIN Schreiber je Slot
    std::uint64_t      kapazitaet    = 0u;
    std::uint64_t      verworfen     = 0u;
};
static_assert(sizeof(SlotBlock) == kCkptLine, "ein Slot-Block je Cache-Line -- sonst False Sharing");

extern SlotBlock g_ckpt_slots[kCheckpointSlots + 1u];   // +1 = der Muell-Slot

// == 6. STRATEGIEN (GoF Strategy, compile-time gewaehlt) =========================================
struct ZyklusZaehler {
    [[nodiscard]] static inline std::uint64_t jetzt() noexcept {
#if defined(__x86_64__)
        return __rdtsc();                      // NICHT rdtscp: doppelt so teuer, und die Ordnung
                                               // je Slot kommt aus der Anhaenge-Reihenfolge
#elif defined(__aarch64__)
        std::uint64_t v; asm volatile("mrs %0, cntvct_el0" : "=r"(v)); return v;
#else
        return 0u;
#endif
    }
};

struct NormalAblage {
    static inline void lege_ab(CheckpointEintrag* z, CheckpointEintrag const& e) noexcept { *z = e; }
    static inline void abschluss() noexcept {}
};
#if defined(__x86_64__) && defined(__SSE2__)
// NICHT-TEMPORAL: der Fuehler darf die Messung nicht aus dem L1 verdraengen. Ein Anhang-Log mit
// normalen Stores verfaelscht eine L1-residente Arbeitslast um +44,4 %, mit movntdq um +2,1 %.
// Das ist keine Durchsatz-Optimierung, sondern die Umsetzung von "der Messfuehler ist ein
// Verbraucher". EIN sfence beim Auslesen je Slot -- nie je Satz.
struct StromAblage {
    static inline void lege_ab(CheckpointEintrag* z, CheckpointEintrag const& e) noexcept {
        __m128i v; std::memcpy(&v, &e, sizeof(v));
        _mm_stream_si128(reinterpret_cast<__m128i*>(z), v);
    }
    static inline void abschluss() noexcept { _mm_sfence(); }
};
using StandardAblage = StromAblage;
#else
using StandardAblage = NormalAblage;   // RISC-V hat kein movnt-Gegenstueck im Basis-ISA
#endif
using StandardZeit = ZyklusZaehler;

// == 7. DIE EINE UNIFORME FUNKTION ===============================================================
// AktivMaske: Bit i == 1 <=> Ebene i ist in DIESER CEB-Variante einkompiliert. Der Wert ist
// TU-ABHAENGIG und wird deshalb -- wie kMessGatesTuGlied (abi/mess_gates_glied.hpp:39-51) -- AM
// MAKRO-EXPANSIONSORT gereicht und NIEMALS ueber eine Entitaet mit externer Bindung. Sonst waehlte
// der Linker still EINE Definition und eine TU meldete eine falsche Ebene, ohne jede Diagnose
// (IFNDR). Genau diese Falle ist im Haus schon einmal beschrieben und hier bewusst nicht geoeffnet.
template <std::uint32_t Stelle, Ebene E, std::uint32_t AktivMaske, CheckpointTag TagT,
          class Zeit = StandardZeit, class Ablage = StandardAblage>
[[gnu::always_inline]] inline void checkpoint_measure(TagT) noexcept {
    static_assert(Stelle <= kStelleMax, "site_id ueberschreitet 29 Bit");
    if constexpr (((AktivMaske >> static_cast<std::uint32_t>(E)) & 1u) == 0u) {
        return;                                     // 0 Instruktionen -- am Objekt belegt
    } else {
        SlotBlock&          b = g_ckpt_slots[t_slot];
        std::uint64_t const i = b.schreib_index;
        if (i >= b.kapazitaet) [[unlikely]] { ++b.verworfen; return; }   // Sect. 8: zaehlen, melden
        CheckpointEintrag const e{kStelleGepackt<Stelle, E, TagT>, 0u, Zeit::jetzt()};
        Ablage::lege_ab(b.puffer + i, e);
        b.schreib_index = i + 1u;
    }
}

} // namespace comdare::cache_engine::measurement::ckpt

// == 8. DAS PFLICHT-MAKRO ========================================================================
// Ohne Makro geht es nicht, und das ist der SAUBERE Weg, nicht der Behelfsweg: beide NTTP-Wege
// sind am Objekt tot -- std::source_location ist kein strukturaler Typ (privates _M_impl), und ein
// Zeiger in ein String-Literal ist kein gueltiges Template-Argument. Das Haus macht es an genau
// dieser Stelle genauso (COMDARE_ANATOMY_VERSION_STAMP_M).
#if !defined(COMDARE_CKPT_EBENE)
#error "COMDARE_CKPT_EBENE fehlt -- die Mess-Ebene wird ueber CMake einkompiliert."
#endif
#if !defined(COMDARE_CKPT_TU_BASIS)
#error "COMDARE_CKPT_TU_BASIS fehlt -- die CMake-Naht muss je TU eine Stellen-Basis reichen."
#endif
#if !defined(COMDARE_CKPT_AKTIV)
#error "COMDARE_CKPT_AKTIV fehlt -- die Maske der einkompilierten Ebenen kommt aus DERSELBEN Aufloesung wie die Gate-Defines."
#endif

// Explizite Ebene -- fuer die TUs, die nachweislich zwei Ebenen tragen (die Tier-TU tut das).
#define COMDARE_CKPT_E(KONFIG, EBENE_AUSDRUCK, TAGWERT)                                            \
    do {                                                                                           \
        static constexpr std::uint32_t kCkptStelle_ =                                              \
            static_cast<std::uint32_t>(COMDARE_CKPT_TU_BASIS)                                      \
            + static_cast<std::uint32_t>(__COUNTER__);                                             \
        [[maybe_unused]] __attribute__((section("comdare_ckpt"), used, retain, aligned(8)))        \
        static constexpr ::comdare::cache_engine::measurement::ckpt::CheckpointSite kCkptSite_ =   \
            ::comdare::cache_engine::measurement::ckpt::make_site<KONFIG>(kCkptStelle_,            \
                                                                         (EBENE_AUSDRUCK));        \
        ::comdare::cache_engine::measurement::ckpt::checkpoint_measure<kCkptStelle_,               \
            (EBENE_AUSDRUCK), static_cast<std::uint32_t>(COMDARE_CKPT_AKTIV)>(TAGWERT);            \
    } while (false)

// Die Regelform -- die Ebene kommt aus dem CMake-Flag, wie die Spezifikation es verlangt.
#define COMDARE_CKPT(KONFIG, TAGWERT)                                                              \
    COMDARE_CKPT_E(KONFIG,                                                                         \
        static_cast<::comdare::cache_engine::measurement::ckpt::Ebene>(COMDARE_CKPT_EBENE), TAGWERT)

// ------------------------------------------------------------------------------------------------
// AUFRUFSTELLE, wie sie im Achsen-Code steht:
//     COMDARE_CKPT(Komposition, ck::IN);
//     ... der gemessene Aufruf ...
//     COMDARE_CKPT(Komposition, ck::OUT);
// EINE Funktion, zwei Zeilen. Zwei Eintraege entstehen, weil die Zeile zweimal steht.
// ------------------------------------------------------------------------------------------------

result:
# `checkpoint_measure(..., IN|OUT)` — SOLL-DESIGN, ENDFASSUNG

**08.08.2026 · Status: Spezifikation ausgearbeitet, gegen drei Skeptiker-Durchgänge gehärtet, NOCH NICHT GEBAUT.**
Supersedet `docs/architecture/20260808-checkpoint_measure_soll_design.md` (erster Stand, 08.08. vormittags).
Verbatim-Quelle der Spezifikation: `super docs/DIPLOMARBEIT-ZIELE-OFFENE-PUNKTE-LEDGER.md`, C-1..C-13 und N-1..N-7.

**Beleg-Kennzeichnung, durchgehend.** `[OBJ]` = am Objekt in diesem Baum gelesen (Datei:Zeile genannt).
`[MESS]` = auf prod1 gemessen, warme Werte, Median aus Wiederholungen. `[UNGEPRUEFT]` = Annahme, ausdrücklich
nicht belegt. Es steht kein Häkchen ohne eine dieser drei Marken.

**Messumgebung für alle `[MESS]`-Zahlen, damit sie niemand überstrapaziert.** prod1 (Ryzen 9 9950X3D,
GCC 15.3, `-O2 -march=native`) trug während der Messungen die Last von rund 50 nebenläufigen Agenten.
Keine Frequenzfixierung, gepinnte Ad-hoc-Benchmarks außerhalb der CEB. Sie tragen die **Rangfolge und die
Größenordnung**, nicht absolute Aussagen. Für ARM und RISC-V ist **nichts** am Objekt geprüft — auf prod1
ist kein Cross-Compiler installiert, der Cluster ist lesend.

---

## 1. Zweck

Eine **inline Steuerzeile** an den Mess-Punkten. Sie schreibt auf einen prozessweit erreichbaren,
**rein anhängenden** Log und dokumentiert damit den Lauf: wer rief, was wurde erreicht, wann, unter welchen
compile-time Achsen-Parametern, und ob der Punkt betreten (`IN`) oder verlassen (`OUT`) wurde.

Vier Sätze der Spezifikation sind bindend und bestimmen das ganze Design:

1. **Eine uniforme Funktion.** Nicht `enter()`/`leave()`. `IN`/`OUT` ist ein **compile-time Tag**, kein
   Laufzeit-Parameter, keine Verzweigung. Zwei Einträge entstehen, weil die Zeile zweimal steht.
2. **Der Aufrufer wird rekonstruiert, nicht gemessen.** Jeder Checkpoint trägt compile-time seine
   **Mess-Ebene**; der Aufrufer ist der nächstgelegene rückwärts liegende offene `IN` der nächsthöheren
   aktiven Ebene. Aufgelöst wird **beim Auslesen**. **Eigener** Stacktrace, ausdrücklich nicht `std::stacktrace`.
3. **Die Thread-Nummer kommt aus virtuellen Slots**, deren Obergrenze die Thread-Unterachse compile-time
   nennt. Kein OS-Aufruf im Hot-Path. Vergabe zu Beginn, Auswertung am Schluss.
4. **Sparsamkeit ist harte Randbedingung.** *„Der Messfühler ist ein Verbraucher — was der Checkpoint
   kostet, misst er mit."*

**Was diese Endfassung gegenüber dem Entwurf ändert — die vier schwersten Punkte vorab:**

| # | Der Entwurf sagte | Die Endfassung sagt | Grund |
|---|---|---|---|
| A | `__rdtsc()` in jedem Checkpoint, ~7,3 ns, 96 % der Kosten | **Die Uhr ist eine Strategie je Ebene**, drei Formen (roh / geordnet / keine), aus CMake gewählt. Vorgabe bleibt spezifikationstreu (Uhr überall), aber die Wahl ist gebaut und die Zahl liegt dem Owner vor. | Der TSC auf prod1 hat ein **Korn von 43 Ticks = 10,0 ns** `[MESS]`. Die Mikro-Ebene ist damit mit einer rohen Einzelablesung grundsätzlich nicht auflösbar. |
| B | `_mm_stream_si128` ist Vorgabe („stärkster Befund der Research") | **`NormalAblage` ist Vorgabe. `StromAblage` bleibt als Strategie, ist aber belegpflichtig.** | Der Befund „+44,4 % gegen +2,1 %" **reproduziert nicht**; drei unabhängige Gegenkonstruktionen zeigen NT als die gleich gute oder schlechtere Form `[MESS]`. |
| C | `rest(macro) = spanne - kinder_summe` sei ein Satz | **Es ist ein Prüfsatz.** Zwei getrennte Elternfelder: `eltern_ebene` (die Spezifikations-Spalte) und `eltern_direkt` (die Arithmetik). Fehlerklasse für negativen Rest. | Verschachtelung gleicher Ebene ist im Bestand **strukturell**: `axes/lookup/composable/composed_art_trie_search.hpp:41` ruft `Traversal::insert_into<Pool>(...)` — Achse 03a in Achse 04, mit Achse 06 darunter `[OBJ]`. Die alte Rechnung zieht geschachtelte Zeit doppelt ab. |
| D | Slots existieren, die Vergabe „ist ein offener Punkt" | **Die Vergabe ist ausgearbeitet** (§6): RAII-Halter, Freiliste, Abschnitts-Trennsatz, Eindeutigkeits-Beweis. | Das ist der Teil, den der Owner als „besonders sorgfältig ausarbeiten" bezeichnet hat, und der Bestand erzwingt Wiederverwendung: `builder/experiment_tree/parallel_measure_pool.hpp:58-61` legt bei **jedem** `collect_ordered` einen frischen `std::vector<std::thread>` an `[OBJ]`. |

---

## 2. Die Signatur

```cpp
// libs/cache_engine/include/cache_engine/measurement/ckpt/checkpoint_measure.hpp
// Die EINE uniforme Steuerzeile. ASCII-only.
//
// DIESE DATEI IST DER HOT-PATH-HEADER. Sie zieht KEIN measurement/axis_error.hpp und KEIN
// topics/ -- der Fehlerraum liegt in checkpoint_error_classes.hpp, die nur der AUFLOESER zieht.
// Begruendung: die Tier-.so inkludiert diesen Header in JEDER der 19 Achsen-TU-Schliessungen;
// jede zusaetzliche Kante ist eine Baseline-Layering-Aenderung als Nebenwirkung.

#include <array>
#include <concepts>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <source_location>
#include <string_view>
#include <type_traits>
#if defined(__x86_64__)
#include <immintrin.h>
#endif

namespace comdare::cache_engine::measurement::ckpt {

// == 1. DIE COMPILE-TIME TAGS ====================================================================
// Die drei Mess-Ebenen. Der ZAHLENWERT ist die Ebenen-ORDNUNG; ein Checkpoint sucht seinen
// Aufrufer in der naechsthoeheren AKTIVEN Ebene.
//
// DIE NUMMERIERUNG HAT ABSICHTLICH LUECKEN (0, 2, 4 statt 0, 1, 2). Der Zahlenwert wird als
// Immediate in den Maschinencode gebrannt und reist in persistierten Logs. Waere micro==2 und
// spaeter schoebe sich eine Ebene dazwischen, bedeutete derselbe Bitwert in alten und neuen Logs
// Verschiedenes -- ein STILLER Formatbruch. Mit Luecken ist die vierte Ebene (Gattung, Wert 3)
// ADDITIV, ohne dass eine bestehende Zahl ihre Bedeutung wechselt.
// KEIN Laufzeit-Enum: der Wert reist ausschliesslich als Nichttyp-Template-Argument.
enum class Ebene : std::uint32_t {
    Compare = 0u,   // 1 frei
    Macro   = 2u,   // 3 frei -- reserviert fuer die Gattungs-Ebene, falls sie je gebaut wird
    Micro   = 4u,   // 5,6,7 frei
};
inline constexpr std::uint32_t kEbeneBits = 3u;          // 8 Ordnungswerte
inline constexpr std::uint32_t kEbeneMax  = (1u << kEbeneBits) - 1u;

// IN/OUT als LEERE Tag-TYPEN: der Tag steht an der Aufrufstelle woertlich dort, wo der Owner ihn
// hinschreibt, ohne dass ein Laufzeit-Wert entsteht. Die Fallunterscheidung ist if constexpr.
// META ist KEIN Aufrufstellen-Tag. Er kennzeichnet Verwaltungs-Saetze (Abschnittsbeginn,
// Modul-Epoche, Lauf-Anker), die der Aufloeser NICHT auf den Ebenen-Stapel legen darf. Ohne
// eigenen Tag-Wert wuerde ein solcher Satz als IN oder OUT gelesen und der Stapel korrumpiert.
struct InTag   {};
struct OutTag  {};
struct MetaTag {};
inline constexpr InTag   IN{};
inline constexpr OutTag  OUT{};
inline constexpr MetaTag META{};

template <class T>
concept CheckpointTag = std::same_as<T, InTag> || std::same_as<T, OutTag> || std::same_as<T, MetaTag>;

inline constexpr std::uint32_t kTagBits = 2u;
template <CheckpointTag T>
inline constexpr std::uint32_t kTagWert =
    std::same_as<T, InTag> ? 0u : (std::same_as<T, OutTag> ? 1u : 2u);   // 3 = reserviert

// == 2. DIE PACKUNG -- ALLE SCHIEBEWEITEN AUS DEN KONSTANTEN =====================================
// Kein nacktes Literal in einer Schiebeweite. Waeren Maske und Schiebeweite unabhaengig
// geschrieben, verschoebe eine Breitenaenderung die Maske, nicht die Packung -- und das Ergebnis
// waere kein Uebersetzungsfehler, sondern ein still falsch entpacktes Feld.
inline constexpr std::uint32_t kStelleBits = 32u - kEbeneBits - kTagBits;   // 27
inline constexpr std::uint32_t kStelleMax  = (1u << kStelleBits) - 1u;
static_assert(kStelleBits + kEbeneBits + kTagBits == 32u, "Kennungs-Wort ist ueberbelegt");

// Die 27 Stellen-Bits zerfallen weiter. Grund: eine site_id ist sonst nur JE LINK-EINHEIT
// eindeutig, und ein Lauf haelt viele Tier-.so GLEICHZEITIG im Prozess
// (builder/anatomy_module_loader/anatomy_module_loader.cpp:40 dlopen(RTLD_NOW|RTLD_LOCAL), :49
// dlclose). Nach BUILD-MODELL-1DLL-1TU-KLARSTELLUNG.md:15 ist jede .so GENAU EINE TU -- ohne
// Modul-Feld vergaeben also ALLE Tier-Binaries eines Laufs dieselben Zahlen, und die Nutzlast
// "die gelandete Zielfunktion" loeste auf den Deskriptor des falschen Moduls auf.
inline constexpr std::uint32_t kModulBits  = 12u;   // 4096 Module je Lauf
inline constexpr std::uint32_t kLokalBits  = kStelleBits - kModulBits;   // 15 -> 32768 Stellen je TU
inline constexpr std::uint32_t kModulMax   = (1u << kModulBits) - 1u;
inline constexpr std::uint32_t kLokalMax   = (1u << kLokalBits) - 1u;

template <std::uint32_t Stelle, Ebene E, CheckpointTag T>
inline constexpr std::uint32_t kKennung =
    (Stelle & kStelleMax)
    | (static_cast<std::uint32_t>(E) << kStelleBits)
    | (kTagWert<T> << (kStelleBits + kEbeneBits));

[[nodiscard]] constexpr std::uint32_t kennung_stelle(std::uint32_t k) noexcept { return k & kStelleMax; }
[[nodiscard]] constexpr std::uint32_t kennung_ebene(std::uint32_t k) noexcept {
    return (k >> kStelleBits) & kEbeneMax;
}
[[nodiscard]] constexpr std::uint32_t kennung_tag(std::uint32_t k) noexcept {
    return k >> (kStelleBits + kEbeneBits);
}
[[nodiscard]] constexpr std::uint32_t kennung_modul(std::uint32_t k) noexcept {
    return kennung_stelle(k) >> kLokalBits;
}

// == 3. DIE ABI-MARKE -- KEINE inline-KONSTANTE FUER TU-ABHAENGIGE WERTE =========================
// abi/mess_gates_glied.hpp:39-49 schreibt es woertlich vor: ein TU-abhaengiger Wert darf NIEMALS
// Initialisierer einer inline-constexpr-Variablen sein -- inline hebt die sonst implizite interne
// Bindung auf, der Linker waehlt still EINE Definition, der Verstoss ist IFNDR.
// COMDARE_CKPT_SLOTS und COMDARE_CKPT_LINE sind TU-abhaengig UND ABI-tragend: sie bestimmen
// sizeof/alignof(SlotBlock) und damit die Adressrechnung `shl` in JEDEM Checkpoint. Eine
// Abweichung waere kein Diagnose-Fall, sondern ein Schreiben ausserhalb der Tabelle, zur Laufzeit,
// mitten im Messlauf.
// DESHALB: interne Bindung (constexpr OHNE inline) PLUS eine Link-Wache. Praezedenz im Haus:
// ceb_version_stamp.hpp (M-1/D-4 Verdrahtungs-Wache), in mess_gates_glied.hpp:47-48 als Vorbild
// benannt.
#if !defined(COMDARE_CKPT_SLOTS)
#error "COMDARE_CKPT_SLOTS fehlt -- die Obergrenze kommt compile-time aus der Thread-Unterachse."
#endif
#if !defined(COMDARE_CKPT_LINE)
#error "COMDARE_CKPT_LINE fehlt -- die Cache-Line-Groesse kommt je Plattform aus CMake. Ein Default \
waere genau die stille Luege: 64 ist auf generischem AArch64 falsch (GCC nennt 256)."
#endif

constexpr std::uint32_t kCheckpointSlots = static_cast<std::uint32_t>(COMDARE_CKPT_SLOTS);
constexpr std::size_t   kCkptLine        = static_cast<std::size_t>(COMDARE_CKPT_LINE);
static_assert(kCheckpointSlots >= 1u);
static_assert(kCkptLine >= alignof(std::max_align_t) && (kCkptLine & (kCkptLine - 1u)) == 0u,
              "COMDARE_CKPT_LINE muss eine 2er-Potenz und mindestens max_align_t sein");

// Der MUELL-SLOT. Ein Fluss ohne gueltige Nummer zeigt hierher; sein Block hat Kapazitaet 0, also
// faengt ihn DIESELBE Kapazitaets-Verzweigung, die den Ueberlauf faengt. Kein eigener Zweig im
// Hot-Path, kein Wrap-around.
constexpr std::uint32_t kSlotMuell = kCheckpointSlots;

} // namespace comdare::cache_engine::measurement::ckpt

// Der Name traegt die beiden ABI-Zahlen. Weichen zwei Uebersetzungseinheiten ab, gibt es das
// Symbol nicht -- der Bruch faellt beim LINKEN, laut, statt zur Laufzeit, still.
#define COMDARE_CKPT_ABI_MARKE__(S, L) comdare_ckpt_abi_s##S##_l##L
#define COMDARE_CKPT_ABI_MARKE_(S, L)  COMDARE_CKPT_ABI_MARKE__(S, L)
#define COMDARE_CKPT_ABI_MARKE         COMDARE_CKPT_ABI_MARKE_(COMDARE_CKPT_SLOTS, COMDARE_CKPT_LINE)
extern "C" char COMDARE_CKPT_ABI_MARKE;   // definiert GENAU EINMAL in der Mess-Bibliothek
namespace {
// used+retain: sonst optimiert der Compiler die einzige Referenz weg und die Wache verschwindet.
[[maybe_unused, gnu::used, gnu::retain]] char const* const g_ckpt_abi_anker = &COMDARE_CKPT_ABI_MARKE;
}

namespace comdare::cache_engine::measurement::ckpt {

// == 4. DER LOG-EINTRAG ==========================================================================
struct alignas(16) CheckpointEintrag {
    std::uint32_t kennung;   // stelle:27 | ebene:3 | tag:2 -- EIN compile-time Immediate
    std::uint32_t zusatz;    // 0 bei IN/OUT. Bei META: die Meta-Nutzlast (s. Sect. 6).
    std::uint64_t zeit;      // Zeitbasis dieses Checkpoints -- ODER 0, wenn die Ebene keine Uhr traegt
};
static_assert(sizeof(CheckpointEintrag) == 16u);
static_assert(alignof(CheckpointEintrag) == 16u);
static_assert(std::is_trivially_copyable_v<CheckpointEintrag>);
static_assert(kCkptLine % sizeof(CheckpointEintrag) == 0u,
              "Satz muss die Cache-Line ohne Rest kacheln");

// == 5. DER STATISCHE DESKRIPTOR JE AUFRUFSTELLE (GoF Flyweight) =================================
// Im Hot-Path NIE angefasst. Er existiert nur, damit der Leser stelle -> Bedeutung aufloest.
// Deshalb steht im Eintrag eine ID und KEIN Zeiger: nach dlclose einer Tier-.so ist die
// Deskriptor-Adresse nicht mehr gemappt, ein gespeicherter Zeiger baumelt. Derselbe Loader fuehrt
// die Disziplin "vor dem Entladen ernten" bereits fuer den Stempel-POD
// (anatomy_module_loader.cpp:86-87).
//
// ZWEI FUNKTIONS-FELDER, NICHT EINES. Die Spezifikation trennt: der AUFRUFER wird rekonstruiert,
// die gelandete ZIELFUNKTION wird getragen. source_location::current() als Default-Argument wird
// am MAKRO-EXPANSIONSORT ausgewertet und liefert die UMSCHLIESSENDE Funktion -- also den Aufrufer,
// wenn der Checkpoint (wie vorgesehen) UM den gemessenen Aufruf herum steht. Ein einziges Feld
// truege dann den Aufrufer zweimal und das Ziel nie.
struct CheckpointSite {
    std::uint32_t stelle;            // dieselbe stelle wie im Eintrag -- ohne Ordnungsannahme
    std::uint32_t zeile;             // source_location::line()
    Ebene         ebene;             // Vorgabe-Ebene dieser Aufrufstelle
    std::uint32_t achsen_len;
    char const*   stelle_funktion;   // wo die ZEILE steht (source_location::function_name())
    char const*   ziel;              // die GELANDETE Zielfunktion -- Literal am Aufrufort
    char const*   datei;
    char const*   achsen;            // Zeiger auf den GETEILTEN Achsen-Deskriptor (R1: nie kopiert)
};

namespace detail {
// Zwei-Pass-Senken -- 1:1 das Haus-Muster aus builder/build_variant_set_signature.hpp:118-127.
// Erst zaehlen, dann fuellen, beide Paesse ueber DENSELBEN Emitter: die Laenge kann nicht von der
// Ausgabe abweichen. Der Emitter erbt dieselben Namens-/Zeichenvorrat-Wachen wie dort, sonst
// entsteht ein zweiter, ungewachter Signatur-Kanal.
struct CtCountSink { std::size_t n = 0; constexpr void put(char) noexcept { ++n; } };
struct CtFillSink  { char* p = nullptr; std::size_t n = 0; constexpr void put(char c) noexcept { p[n++] = c; } };
template <class Sink> constexpr void ct_put_text(Sink& s, std::string_view t) noexcept {
    for (char c : t) s.put(c);
}
template <class Sink, class Konfig>
constexpr void ct_put_achsen(Sink& s) noexcept {
    ct_put_text(s, std::string_view{"ax=1;"});
    ct_put_text(s, Konfig::achsen_signatur());   // mp11-Typliste -> consteval-String, Haus-Mechanik
}
template <class Konfig> [[nodiscard]] consteval std::size_t achsen_len() noexcept {
    CtCountSink s{}; ct_put_achsen<CtCountSink, Konfig>(s); return s.n;
}
template <class Konfig, std::size_t N>
[[nodiscard]] consteval std::array<char, N> achsen_chars() noexcept {
    std::array<char, N> out{}; CtFillSink s{out.data(), 0}; ct_put_achsen<CtFillSink, Konfig>(s); return out;
}
} // namespace detail

// EINE Kopie je Konfiguration und Binary -- von ALLEN Aufrufstellen derselben Konfiguration geteilt.
template <class Konfig>
inline constexpr auto kAchsenDeskriptorChars =
    detail::achsen_chars<Konfig, detail::achsen_len<Konfig>()>();

template <class Konfig>
[[nodiscard]] consteval CheckpointSite make_site(
    std::uint32_t stelle, Ebene ebene, char const* ziel,
    std::source_location const loc = std::source_location::current()) noexcept {
    return CheckpointSite{stelle,
                          static_cast<std::uint32_t>(loc.line()),
                          ebene,
                          static_cast<std::uint32_t>(kAchsenDeskriptorChars<Konfig>.size()),
                          loc.function_name(),
                          ziel,
                          loc.file_name(),
                          kAchsenDeskriptorChars<Konfig>.data()};
}

// == 6. DER SLOT ================================================================================
// Die EINE Definition liegt in der beim START GELINKTEN gemeinsamen Mess-Bibliothek; jede Tier-.so
// DEKLARIERT sie nur. Damit traegt die Tier-.so KEIN eigenes TLS-Segment und verbraucht null
// statischen TLS-Vorrat. Der Vorrat ist ein PROZESSWEITES, kumulatives Budget (glibc, rund
// 1665 Byte): sechs dlopen-geladene .so mit je 256 B eigenem IE-TLS laden noch, die siebte bricht
// mit "cannot allocate memory in static TLS block" -- zur LAUFZEIT, mitten im Messlauf.
//
// DIE DEFINITION STEHT HIER AUSGESCHRIEBEN, WEIL IHR ANFANGSWERT TRAGEND IST:
//     constinit thread_local std::uint32_t t_slot = kSlotMuell;
// Ohne den Initialisierer waere er 0 -- und Slot 0 ist ein GUELTIGER Slot mit echter Kapazitaet.
// Jeder Fluss, der die Vergabe nie durchlaeuft (Allokator-Hintergrundfaden, Faden aus einem
// fremden dlopen-Modul, Fremdpool), schriebe dann in den Puffer des rechtmaessigen Besitzers von
// Slot 0: zwei Schreiber auf einem nichtatomaren schreib_index, also ein Datenrennen, und zwei
// verschraenkte IN/OUT-Folgen in EINEM Stapel.
// constinit ist PFLICHT und nicht Stil -- nicht wegen Portabilitaet (dieser Header nutzt ohnehin
// gnu::always_inline, section/used/retain, __start_/__stop_, Inline-Asm), sondern weil es die
// Guard-Freiheit zu einer UEBERSETZUNGS-Wache macht. Ohne constinit steht ueber der Modulgrenze
// ein nie genommener Guard-Zweig, der trotzdem je Zugriff kostet und im Quelltext unsichtbar ist.
extern constinit thread_local std::uint32_t t_slot;

struct alignas(kCkptLine) SlotBlock {
    CheckpointEintrag* puffer        = nullptr;
    std::uint64_t      schreib_index = 0u;   // GEWOEHNLICH, kein atomic -- EIN Schreiber je Slot
    std::uint64_t      kapazitaet    = 0u;
    std::uint64_t      verworfen     = 0u;   // AUSNAHME Muell-Slot, s. u.
};
static_assert(sizeof(SlotBlock) == kCkptLine, "ein Slot-Block je Cache-Line -- sonst False Sharing");

// UNVOLLSTAENDIGER ARRAY-TYP mit Absicht: so kann keine TU eine abweichende Feldgrenze in den
// Typ schreiben. Die Grenze steht ausschliesslich in der Definition der Mess-Bibliothek; die
// ABI-Marke oben erzwingt, dass alle TUs von derselben Zahl ausgehen.
extern SlotBlock g_ckpt_slots[];

// == 7. DIE ZEIT-STRATEGIEN (GoF Strategy, compile-time gewaehlt, JE EBENE) ======================
// DREI Formen, weil die Zeitquelle drei unvereinbare Anforderungen hat und keine Form alle traegt.
// Die Zahlen sind auf prod1 gemessen, mit dem Vorbehalt aus dem Kopf dieses Dokuments.
//
//  (a) RohZeit       __rdtsc nackt. 7,29 ns. Nicht serialisierend: die OOO-Maschine fuehrt es
//                    aus, wo es passt, nicht wo es steht. Unter einer geschachtelten Arbeitslast
//                    kostet der Checkpoint dadurch NUR 1,8 bis 3,5 ns -- weil er in den
//                    Latenzschatten faellt. Derselbe Grund macht ihn UNVERORTET: fuer
//                    Kettenlaengen 0/1/2/4/8/16 misst er identisch Median 42 Ticks.
//  (b) GeordneteZeit lfence;rdtsc. 12,02 ns nackt, 15,32 ns unter echtem Opfer. Verortet: derselbe
//                    Aufbau steigt sauber (min 43/43/43/43/86/86). Der Preis ist real.
//  (c) KeineZeit     schreibt 0. Fuer Ebenen, deren Einzelspannen ohnehin unter dem KORN der
//                    Maschine liegen (auf prod1 43 Ticks = 10,0 ns, s. Sect. 9 des Dokuments).
//                    Die Aufrufer-Rekonstruktion benutzt den Stempel UEBERHAUPT NICHT -- sie
//                    laeuft rein ueber die Anhaenge-Reihenfolge je Slot. Die STRUKTUR bleibt also
//                    vollstaendig; nur die DAUER faellt weg, und sie war an dieser Stelle
//                    ohnehin nicht darstellbar.
struct RohZeit {
    [[nodiscard]] static inline std::uint64_t jetzt() noexcept {
#if defined(__x86_64__)
        return __rdtsc();
#elif defined(__aarch64__)
        std::uint64_t v; asm volatile("mrs %0, cntvct_el0" : "=r"(v)); return v;
#elif defined(__riscv) && __riscv_xlen == 64
        std::uint64_t v; asm volatile("rdtime %0" : "=r"(v)); return v;
#else
#error "checkpoint_measure: keine Zeitquelle fuer dieses Ziel. Ein stiller 0-Ruecklauf ist \
verboten -- er macht jede Dauer 0, laesst die Inversions-Wache nie feuern und degeneriert den \
Merge-Schluessel, ohne einen einzigen Befund zu erzeugen. Eine Messmaschine ohne Uhr baut nicht."
#endif
    }
};

struct GeordneteZeit {
    [[nodiscard]] static inline std::uint64_t jetzt() noexcept {
#if defined(__x86_64__)
        _mm_lfence();
        return __rdtsc();
#else
        return RohZeit::jetzt();   // ARM/RISC-V-Ordnungsform ist UNGEPRUEFT, s. offener Entscheid 6
#endif
    }
};

struct KeineZeit {
    [[nodiscard]] static inline std::uint64_t jetzt() noexcept { return 0u; }
};

// == 8. DIE ABLAGE-STRATEGIEN ===================================================================
// NormalAblage ist die VORGABE. Der Entwurf hatte StromAblage (movntdq) als Vorgabe, gestuetzt auf
// den Research-Befund "+44,4 % Verfaelschung mit normalem Store gegen +2,1 % mit NT". DIESER
// BEFUND REPRODUZIERT NICHT: drei unabhaengige Gegenkonstruktionen (L1-residentes
// Zeiger-Verfolgungs-Opfer auf drei Kernen; Dichte-Sweep 1..64 Spruenge; schreiblastiges Opfer)
// zeigen NT als gleich gut oder SCHLECHTER, mit wechselndem Vorzeichen im Bereich +-1
// Prozentpunkt. StromAblage bleibt gebaut, ist aber BELEGPFLICHTIG -- nicht Vorgabe.
struct NormalAblage {
    static inline void lege_ab(CheckpointEintrag* z, CheckpointEintrag const& e) noexcept { *z = e; }
    static inline void versiegle() noexcept {}
};

#if defined(__x86_64__) && defined(__SSE2__)
struct StromAblage {
    static inline void lege_ab(CheckpointEintrag* z, CheckpointEintrag const& e) noexcept {
        __m128i v; std::memcpy(&v, &e, sizeof(v));
        _mm_stream_si128(reinterpret_cast<__m128i*>(z), v);
    }
    // versiegle() LAEUFT AUF DEM SCHREIBENDEN KERN, beim Freigeben des Slots -- nicht beim Leser.
    // sfence ordnet die Stores DES AUSFUEHRENDEN Prozessors; im Leser-Faden ausgefuehrt hat er auf
    // die Write-Combining-Puffer des Schreibers keine Wirkung.
    static inline void versiegle() noexcept { _mm_sfence(); }
};
#endif
using StandardAblage = NormalAblage;

// == 9. DIE EINE UNIFORME FUNKTION ==============================================================
// AktivMaske: Bit i == 1 <=> Ebene i ist in DIESER Uebersetzungseinheit einkompiliert.
// Sie ist TU-ABHAENGIG und wird deshalb -- wie kMessGatesTuGlied -- AM MAKRO-EXPANSIONSORT
// gereicht und NIEMALS ueber eine Entitaet mit externer Bindung. Bissprobe im Haus vorhanden:
// TU-A mit -D=2 und TU-B mit -D=1 uebersetzt, gemeinsam gelinkt -> TU-B meldet 2 statt 1, gleiche
// Adresse, null Compiler-/Linker-Warnungen.
//
// SIE IST NICHT DIESELBE GROESSE, DIE DER AUFLOESER BRAUCHT. Der Aufloeser braucht die Menge der
// Ebenen, die im PROZESS zur fraglichen Zeit vorkommen -- und die ist zeitabhaengig, weil
// Tier-Binaries per dlopen/dlclose kommen und gehen. Diese zweite Groesse heisst
// EbenenPraesenz und wird beim Auslesen aus der geernteten Deskriptor-Sektion je Modul erhoben,
// nicht aus einem Define. Zwei Namen, zwei Groessen, kein gemeinsamer Kanal.
template <std::uint32_t Stelle, Ebene E, std::uint32_t AktivMaske, CheckpointTag TagT,
          class Zeit = RohZeit, class Ablage = StandardAblage>
[[gnu::always_inline]] inline void checkpoint_measure(TagT, std::uint32_t zusatz = 0u) noexcept {
    static_assert((Stelle & ~kStelleMax) == 0u, "stelle ueberschreitet 27 Bit");
    static_assert(static_cast<std::uint32_t>(E) <= kEbeneMax, "Ebene ueberschreitet 3 Bit");
    if constexpr (((AktivMaske >> static_cast<std::uint32_t>(E)) & 1u) == 0u) {
        (void)zusatz;
        return;                                     // 0 Instruktionen -- am Objekt belegt
    } else {
        SlotBlock&          b = g_ckpt_slots[t_slot];
        std::uint64_t const i = b.schreib_index;
        if (i >= b.kapazitaet) [[unlikely]] { ++b.verworfen; return; }
        CheckpointEintrag const e{kKennung<Stelle, E, TagT>, zusatz, Zeit::jetzt()};
        Ablage::lege_ab(b.puffer + i, e);
        b.schreib_index = i + 1u;
    }
}

} // namespace comdare::cache_engine::measurement::ckpt

// == 10. DAS PFLICHT-MAKRO ======================================================================
// Ohne Makro geht es nicht, und das ist der SAUBERE Weg, nicht der Behelfsweg: std::source_location
// ist kein strukturaler Typ (privates _M_impl), und ein Zeiger in ein String-Literal ist kein
// gueltiges Template-Argument. Das Haus macht es an genau dieser Stelle genauso
// (COMDARE_ANATOMY_VERSION_STAMP_M).
#if !defined(COMDARE_CKPT_EBENE)
#error "COMDARE_CKPT_EBENE fehlt -- die Vorgabe-Mess-Ebene wird ueber CMake einkompiliert."
#endif
#if !defined(COMDARE_CKPT_TU_BASIS)
#error "COMDARE_CKPT_TU_BASIS fehlt -- Modul-ID und TU-Basis kommen aus der Bau-Naht."
#endif
#if !defined(COMDARE_CKPT_AKTIV)
#error "COMDARE_CKPT_AKTIV fehlt -- die Maske der einkompilierten Ebenen kommt aus DERSELBEN \
Aufloesung wie die Gate-Defines."
#endif

// Explizite Ebene -- fuer die TUs, die nachweislich zwei Ebenen tragen (die Tier-TU tut das).
#define COMDARE_CKPT_E(KONFIG, EBENE_AUSDRUCK, ZIEL_LITERAL, TAGWERT)                              \
    do {                                                                                           \
        static constexpr std::uint32_t kCkptStelle_ =                                              \
            static_cast<std::uint32_t>(COMDARE_CKPT_TU_BASIS)                                      \
            + static_cast<std::uint32_t>(__COUNTER__);                                             \
        [[maybe_unused]] __attribute__((section("comdare_ckpt"), used, retain, aligned(8)))         \
        static constexpr ::comdare::cache_engine::measurement::ckpt::CheckpointSite kCkptSite_ =   \
            ::comdare::cache_engine::measurement::ckpt::make_site<KONFIG>(                         \
                kCkptStelle_, (EBENE_AUSDRUCK), (ZIEL_LITERAL));                                   \
        ::comdare::cache_engine::measurement::ckpt::checkpoint_measure<                            \
            kCkptStelle_, (EBENE_AUSDRUCK), static_cast<std::uint32_t>(COMDARE_CKPT_AKTIV)>(        \
                TAGWERT);                                                                          \
    } while (false)

// Die Regelform -- die Ebene kommt aus dem CMake-Flag, wie die Spezifikation es verlangt.
#define COMDARE_CKPT(KONFIG, ZIEL_LITERAL, TAGWERT)                                                \
    COMDARE_CKPT_E(KONFIG,                                                                         \
        static_cast<::comdare::cache_engine::measurement::ckpt::Ebene>(COMDARE_CKPT_EBENE),         \
        ZIEL_LITERAL, TAGWERT)

// -----------------------------------------------------------------------------------------------
// AUFRUFSTELLE, wie sie im Achsen-Code steht:
//     COMDARE_CKPT(Komposition, "Traversal::insert_into", ck::IN);
//     Traversal::template insert_into<Pool>(pool_, k, v);
//     COMDARE_CKPT(Komposition, "Traversal::insert_into", ck::OUT);
// EINE Funktion, zwei Zeilen. Zwei Eintraege entstehen, weil die Zeile zweimal steht.
// -----------------------------------------------------------------------------------------------
```

---

## 3. Das Eintrags-Layout

**EINTRAG = 16 BYTE. VIER JE 64-BYTE-CACHE-LINE, OHNE ÜBERHANG.** `[MESS]` an der Probe:
`sizeof(Eintrag)=16`, `je_line=4`, `sizeof(SlotBlock)=64`.

| Offset | Größe | Feld | Inhalt |
|---:|---:|---|---|
| 0 | 4 B | `kennung` | `stelle:27` \| `ebene:3` \| `tag:2` — **ein** compile-time Immediate |
| 4 | 4 B | `zusatz` | 0 bei `IN`/`OUT`. Bei `META` die Meta-Nutzlast (Abschnittsnummer, Epochen-ID). |
| 8 | 8 B | `zeit` | Zeitbasis dieses Checkpoints — **oder 0**, wenn die Ebene `KeineZeit` trägt |

**`stelle` zerfällt weiter:** `modul:12` (Bit 15..26) \| `lokal:15` (Bit 0..14). Also **4096 Module je Lauf**,
**32768 Aufrufstellen je Übersetzungseinheit**. Beides ist eine harte Grenze und wird gefangen: `lokal` per
`static_assert` beim Übersetzen, `modul` bei der Vergabe durch die CEB (`ckpt_modul_raum_erschoepft`).

**Warum `stelle` und nicht ein Zeiger.** Nicht Latenz — beide Formen sind latenzseitig gleichwertig. Der
Grund ist `dlclose`: die Tier-Binaries werden real per `dlopen`/`dlclose` gefahren
(`anatomy_module_loader.cpp:40` / `:49`) `[OBJ]`, nach dem Entladen ist die Deskriptor-Adresse nicht mehr
gemappt, jeder abgelegte Zeiger baumelt. Eine ID überlebt das Entladen.

**Warum 16 statt 8 Byte.** Der Entwurf hatte das schon entschieden, die Skeptiker haben es nicht bestritten,
und der Grund bleibt: die Spezifikation nennt *„die Systemzeit"*, und die 8-Byte-Form ersetzt sie durch ein
32-Bit-Delta gegen einen Slot-Anker, dessen **Kadenz nicht ausgelegt ist** (Wrap bei ~0,93 s auf 4,3 GHz).
Auf eine nicht ausgelegte Kadenz zu bauen wäre der Behelfsweg. Kostenseitig sind alle Eintragsformen
ununterscheidbar (7,444–7,474 ns, `[MESS]`), weil die Zeitquelle alles dominiert. **Der Preis ist Kapazität,
nicht Latenz** — s. §5 und `--check-size`.

**Warum das Kennungs-Wort so und nicht anders.**

* `tag` hat **2 Bit**, nicht 1. Der dritte Wert (`META`) ist tragend: Verwaltungssätze müssen als
  nicht-stapelwirksam erkennbar sein. Der Entwurf sah einen „Epochen-Satz" vor, hatte aber kein Feld dafür —
  er wäre von Phase 1 als `IN` oder `OUT` gelesen worden und hätte den Ebenen-Stapel korrumpiert.
* `ebene` hat **3 Bit** mit **Lücken in der Nummerierung** (Compare=0, Macro=2, Micro=4). Damit ist eine
  vierte Ebene additiv, ohne dass ein bestehender Zahlenwert seine Bedeutung wechselt. Die Lücke 3 ist
  namentlich für die Gattungs-Ebene reserviert, falls sie je gebaut wird.
* Alle Schiebeweiten sind **aus den Breiten-Konstanten abgeleitet**, keine nackten Literale, plus
  `static_assert` auf die Summe 32.

**NICHT im Eintrag — und warum:**

| Nicht drin | Wo stattdessen |
|---|---|
| Thread-Nummer | **Der Slot ist der Thread.** Der Puffer gehört genau einem Slot. Die Nummer je Satz zu schreiben wäre Redundanz; sie steht beim Auslesen in jeder Zeile. |
| Abschnitt (bei Slot-Wiederverwendung) | Als `META`-**Trennsatz** beim Slot-Erwerb (§6). Kostet null im Hot-Path. Die Alternative — `zusatz` je Satz mit der Abschnittsnummer füllen — kostet eine Ladung aus der ohnehin heißen Slot-Line plus ein `or` und bleibt als Rückfall benannt, falls sich der Trennsatz als verlierbar erweist. |
| Prozess-Name | Einmal beim Start ermittelt, im Lauf-Kopf. Null Kosten je Checkpoint. |
| Zielfunktion / aufrufende Funktion | Im Deskriptor, als **zwei** Felder (`ziel`, `stelle_funktion`). |
| Achsen-Parameter | **Zeiger** im Deskriptor auf den GETEILTEN Achsen-String. `[MESS]` an der Probe: vier Aufrufstellen, **ein** String (61 Byte, 4/4 adressgleich). Das ist R1 wörtlich. |
| Modul-Epoche | In den `modul`-Bits der `stelle` (compile-time) plus `META`-Sätze im Loader-eigenen Slot. |
| Aufrufer | Gar nicht — er wird beim Auslesen rekonstruiert. |

**SLOT-BLOCK = 64 BYTE, genau eine Cache-Line.** Das Padding ist Pflicht und verwacht: ein ungepolsterter
16-Byte-Kontrollblock legt zwei Slots auf dieselbe Line und kostet Faktor 2,4 (2 Threads) bis 5,6 (16 Threads
über zwei CCD) `[MESS]`. Die Konstante ist **nicht** hartkodiert und hat **keinen Default** — GCC 15.3 löst
`-Winterference-size` hier real aus, und `SlotBlock` ist ABI-sichtbar, weil die Tier-.so die Tabelle liest,
die die Mess-Bibliothek definiert.

**DESKRIPTOR = 40 B + 8 B (zweites Funktionsfeld) = 48 Byte**, in `.rodata`, Sektion `comdare_ckpt`, im
Hot-Path nie angefasst. Der Linker sammelt die Deskriptoren je Link-Einheit zu einem dichten Array;
`__start_`/`__stop_` geben die Grenzen. Die Dichte entsteht beim **Linken**, nicht beim Übersetzen — deshalb
braucht es keinen Codegen-Schritt (und kein Python, das ohnehin verboten wäre).

**KAPAZITÄT, die daraus folgt und in `--check-size` gehört.** 19 Achsen × 2 = 38 Sätze je Interface-Aufruf ×
16 Byte = **608 Byte je Interface-Aufruf**. Bei Owner-Batch 4096 sind das 155 648 Sätze je Thread = 2,38 MiB;
über 64 Slots 152 MiB. Ein Lauf mit 10⁹ Interface-Aufrufen erzeugt 608 GB.

**BANDBREITE, die ebenfalls in `--check-size` gehört** — sie fehlte im Entwurf vollständig. Formel:
`Schreiblast [GB/s] = belegte_Slots × 16 B / ns-je-Checkpoint`. `[MESS]` mit `StromAblage`: 1 Slot 2,01 GB/s ·
2 Slots 4,04 · 4 Slots 8,23 · 8 Slots 16,39 · 16 Slots 30,89 GB/s, gegen ein Maschinendach von 66,8 GB/s.
Bei 16 Slots frisst allein der Messfühler **46 % des Schreibbands** — genau die Ressource, um die es bei
einer CacheEngine-Messung geht. Bei `COMDARE_CKPT_SLOTS=64` läge die Log-Schreiblast rechnerisch **über dem
Dach**. Mit `NormalAblage` als Vorgabe fängt die Cache-Hierarchie einen Teil davon ab, aber die Rechnung
gehört trotzdem in `--check-size`, und sie erzeugt eine harte Obergrenze für `belegte Slots × Checkpoint-Dichte`.

